/**
 * PhysicsDebug - 3D debug overlay for physics bodies
 *
 * Renders physics state information as billboarded text labels
 * above each body in the scene.
 */
export class PhysicsDebug {
    /**
     * @param {Object} physics - Physics instance
     * @param {Object} options - Configuration options
     * @param {number} [options.yOffset=2.0] - Height offset above bodies
     * @param {number} [options.fontSize=0.15] - Text font size
     * @param {number} [options.updateInterval=100] - Content update interval in ms
     */
    constructor(physics: any, options?: {
        yOffset?: number;
        fontSize?: number;
        updateInterval?: number;
    });
    physics: any;
    yOffset: number;
    fontSize: number;
    updateInterval: number;
    _dynamicTexts: any[];
    _kinematicTexts: any[];
    _staticTexts: any[];
    _zoneTexts: any[];
    _dynamicVisible: boolean;
    _kinematicVisible: boolean;
    _staticVisible: boolean;
    _zoneVisible: boolean;
    _lastUpdateTime: number;
    _needsSync: boolean;
    _initialized: boolean;
    _initBatchedText(): void;
    batchedText: BatchedText;
    /**
     * Initialize GPU culling (call after renderer is available)
     * @param {THREE.WebGPURenderer} renderer
     */
    initCuller(renderer: THREE.WebGPURenderer): void;
    /**
     * Toggle visibility of dynamic body labels
     * @param {boolean} visible
     */
    setDynamicVisible(visible: boolean): void;
    /**
     * Toggle visibility of kinematic body labels
     * @param {boolean} visible
     */
    setKinematicVisible(visible: boolean): void;
    /**
     * Toggle visibility of static body labels
     * @param {boolean} visible
     */
    setStaticVisible(visible: boolean): void;
    /**
     * Toggle visibility of zone labels
     * @param {boolean} visible
     */
    setZoneVisible(visible: boolean): void;
    _updateVisibility(): void;
    _addTextForBody(type: any, index: any, body: any): {
        text: Text;
        instanceId: number;
        type: any;
        index: any;
        pendingSync: boolean;
    };
    _addStaticTextForBody(index: any, _body: any, object3d: any): {
        text: Text;
        instanceId: number;
        type: string;
        index: any;
        pendingSync: boolean;
        matrixSynced: boolean;
    };
    _addZoneTextForBody(index: any, _body: any, object3d: any): {
        text: Text;
        instanceId: number;
        type: string;
        index: any;
        pendingSync: boolean;
        matrixSynced: boolean;
    };
    _removeTextForBody(type: any, index: any): void;
    /**
     * Safely set matrix at instanceId, checking if still valid.
     * @private
     */
    private _safeSetMatrixAt;
    _formatDynamicText(index: any, body: any): string;
    _formatKinematicText(index: any, body: any): string;
    _formatStaticText(index: any, body: any, object3d: any): string;
    _formatZoneText(index: any, body: any, object3d: any): string;
    _shouldUpdateContent(time: any): boolean;
    _getDynamicApi(index: any): any;
    _getKinematicApi(index: any): any;
    _getStaticApi(index: any): any;
    _getZoneApi(index: any): any;
    /**
     * Update debug overlay - call each frame
     * Note: Required for dynamic/kinematic bodies to stay in sync.
     * @param {THREE.WebGPURenderer} [renderer] - Renderer instance (required for text sync on first call)
     */
    update(renderer?: THREE.WebGPURenderer): void;
    /**
     * Clean up resources
     */
    dispose(): void;
}
import { BatchedText } from '@three-blocks/core';
import { Text } from '@three-blocks/core';
